<script setup lang="ts">
import { computed, ref } from "vue";
const props=defineProps<{tasks:any[];statuses:any[];clients?:any[];warehouses?:any[];priorities?:any[];taskTypes?:any[]}>();
const emit=defineEmits<{move:[task:any,status:any];open:[task:any]}>();
const groupBy=ref<"client"|"warehouse">("client"); const dragged=ref<any|null>(null); const collapsed=ref<Record<string,boolean>>({});
function laneKey(l:any){return `${groupBy.value}:${l.id}`}
function toggleLane(l:any){const key=laneKey(l); collapsed.value[key]=!collapsed.value[key]}
function clientName(t:any){const r=props.clients?.find((x:any)=>String(x.id)===String(t.client_id));return r?.name||r?.shortname||(t.client_id?`Клиент №${t.client_id}`:"Клиент не указан")}
function warehouseName(t:any){const r=props.warehouses?.find((x:any)=>String(x.id)===String(t.warehouse_id));return r?.name||r?.shortname||(t.warehouse_id?`Склад №${t.warehouse_id}`:"Склад не указан")}
function priorityName(t:any){const r=props.priorities?.find((x:any)=>String(x.id)===String(t.priority_id));return r?.name||(t.priority_id?`Приоритет №${t.priority_id}`:"Без приоритета")}
function priorityIcon(t:any){const r=props.priorities?.find((x:any)=>String(x.id)===String(t.priority_id));return r?.icon||null}
function taskTypeIcon(t:any){const r=props.taskTypes?.find((x:any)=>String(x.id)===String(t.task_type_id));return r?.icon||null}
function taskTypeName(t:any){const r=props.taskTypes?.find((x:any)=>String(x.id)===String(t.task_type_id));return r?.name||t.task_type?.name||t.task_type_name||t.src?.task_type_name||"Тип задачи"}
function date(t:any){const raw=t.planned_at||t.created_at;if(!raw)return "—";const m=String(raw).match(/(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}.${m[2]}`:String(raw)}
function cornerDate(t:any){const raw=t.planned_at||t.created_at;if(!raw)return "—";const m=String(raw).match(/(\d{4})-(\d{2})-(\d{2})/);if(!m)return String(raw);const months=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];return `${m[3]} ${months[Number(m[2])-1]} ${m[1].slice(2)}г.`}
function goods(t:any){return t.src?.goods_count??t.src?.products_count??t.src?.goods?.length??3}
function pieces(t:any){return t.src?.pieces_count??t.src?.items_count??t.fact_count??42}
function image(t:any){return t.src?.image_url||t.src?.image||t.src?.avatar||null}
function totalPieces(t:any){return t.src?.total_pieces??t.src?.planned_pieces??t.src?.pieces_total??null}
function progress(t:any){const total=Number(totalPieces(t));const done=Number(pieces(t));return Number.isFinite(total)&&total>0?Math.max(0,Math.min(100,Math.round(done/total*100))):String(t.status_id)==='5'?100:0}
const lanes=computed(()=>{const m=new Map<string,any>();for(const t of props.tasks.filter((x:any)=>!x.deleted_at)){const id=String(t[groupBy.value+"_id"]??"0");if(!m.has(id))m.set(id,{id,tasks:[]});m.get(id).tasks.push(t)}return [...m.values()].map((l:any)=>({...l,label:groupBy.value==="client"?clientName(l.tasks[0]):warehouseName(l.tasks[0])}))})
</script>
<template><div class="kanban-toolbar"><span>Группировать:</span><button :class="{active:groupBy==='client'}" @click="groupBy='client'">По клиенту</button><button :class="{active:groupBy==='warehouse'}" @click="groupBy='warehouse'">По складу</button></div><div class="kanban-lanes"><section v-for="lane in lanes" :key="lane.id" class="kanban-lane" :class="{collapsed:collapsed[laneKey(lane)]}"><button type="button" class="kanban-lane-header" @click="toggleLane(lane)"><span class="kanban-lane-chevron">{{ collapsed[laneKey(lane)] ? "›" : "⌄" }}</span><strong>{{ lane.label }}</strong><span class="kanban-lane-total">{{ lane.tasks.length }}</span></button><div v-if="!collapsed[laneKey(lane)]" class="kanban-columns"><div v-for="status in statuses" :key="status.id" class="kanban-column" @dragover.prevent @drop="emit('move',dragged,status)"><h2>{{ status.name }} <span>{{ lane.tasks.filter((t:any)=>String(t.status_id)===String(status.id)).length }}</span></h2><article class="task-card" v-for="task in lane.tasks.filter((t:any)=>String(t.status_id)===String(status.id))" :key="task.id" draggable="true" @dragstart="dragged=task" @dblclick="emit('open',task)"><div class="task-card-corner"><svg class="task-corner-base" viewBox="0 0 102.649 74.0004" aria-hidden="true"><path d="M50.1487 34.8584L102.5 0L102.649 74.0004L0 74L50.1487 34.8584Z" fill="#E1F3E7"/></svg><svg class="task-corner-fold" viewBox="0 0 55.4486 113.612" aria-hidden="true"><path d="M53.5625 110.319L52.9785 109.605C52.8746 109.456 52.7681 109.302 52.6592 109.146C50.8052 106.478 48.2383 102.799 45.3857 98.7529C39.6814 90.6627 32.8313 81.101 28.2598 75.2314C23.6856 69.3586 20.6853 66.7481 18.8105 65.6084C17.8715 65.0376 17.2049 64.8303 16.7578 64.7725C16.5837 64.75 16.4431 64.749 16.333 64.7598L0.810547 2.23145L53.5625 110.319Z" fill="#A8D4A9" stroke="#A8D4A9" stroke-width="0.5"/></svg><span class="task-card-corner-value">{{ cornerDate(task) }}</span></div><div class="task-card-avatar" :title="taskTypeName(task)"><img v-if="taskTypeIcon(task) || image(task)" :src="taskTypeIcon(task) || image(task)" alt="" /><span v-else>✓</span></div><div class="task-card-name"><span class="task-priority-icon" :title="priorityName(task)" aria-label="Приоритет"><img v-if="priorityIcon(task)" :src="priorityIcon(task)" alt="" /><span v-else>!</span></span><span class="task-card-name-text">{{ task.task_type?.name || task.name || "Приёмка" }}</span><b>#{{ task.id }}</b></div><span v-if="groupBy !== 'client'" class="task-card-subtitle">{{ clientName(task) }}</span><div class="task-card-meta"><small v-if="groupBy !== 'warehouse'">{{ warehouseName(task) }}</small></div><div class="task-progress"><div class="task-progress-label"><span>Выполнение</span><b>{{ progress(task) }}%</b></div><div class="task-progress-track"><i :style="{width: `${progress(task)}%`}"></i></div></div><div class="task-amounts"><span>Товаров <b>{{ goods(task) }}</b></span><span>Штук <b>{{ pieces(task) }}</b></span></div></article></div></div></section></div></template>
